const GH = {
  repo: detectRepo(),
  get token() { return localStorage.getItem("recognition.gh_token") || ""; },
  set token(v) { v ? localStorage.setItem("recognition.gh_token", v) : localStorage.removeItem("recognition.gh_token"); },
  get on() { return !!this.token; },
  get pollMs() { return this.token ? 6000 : 12000; },

  async api(path, opts = {}) {
    const headers = {
      Accept: "application/vnd.github+json",
      "X-GitHub-Api-Version": "2022-11-28",
      ...(opts.headers || {}),
    };
    if (this.token) headers.Authorization = `Bearer ${this.token}`;
    const r = await fetch(`https://api.github.com${path}`, { ...opts, headers });
    if (r.status === 404) return null;
    if (!r.ok) throw new Error(`GitHub ${r.status}: ${(await r.text()).slice(0, 140)}`);
    return r.status === 204 ? true : r.json();
  },

  dispatch(event_type, client_payload) {
    return this.api(`/repos/${this.repo}/dispatches`, {
      method: "POST",
      body: JSON.stringify({ event_type, client_payload }),
    });
  },

  async raw(path, ref) {
    if (!this.token) {
      const r = await fetch(
        `https://raw.githubusercontent.com/${this.repo}/${ref}/${path}?t=${Date.now()}`,
        { cache: "no-store" },
      );
      return r.ok ? r.json().catch(() => null) : null;
    }
    const r = await fetch(
      `https://api.github.com/repos/${this.repo}/contents/${path}?ref=${ref}&t=${Date.now()}`,
      { headers: { Accept: "application/vnd.github.raw+json", Authorization: `Bearer ${this.token}` } },
    );
    return r.ok ? r.json() : null;
  },

  async findRun(workflow, sinceMs) {
    const d = await this.api(`/repos/${this.repo}/actions/runs?per_page=12`);
    return (d?.workflow_runs || []).find(
      (r) => r.path?.endsWith(`/${workflow}.yml`) && Date.parse(r.created_at) >= sinceMs - 20000,
    ) || null;
  },
};

input.new_string:
/* The demo key: a deliberately public, Actions-only token (it can start
   workflow runs on this one repository and nothing else — no code, no
   branches, no secrets). It is what makes the page seamless for every
   visitor; a personal token in Connect takes precedence when present. */
const DEMO_KEY = (typeof window !== "undefined" && window.RECOGNITION_DEMO_KEY) || "";

const GH = {
  repo: detectRepo(),
  get token() { return localStorage.getItem("recognition.gh_token") || ""; },
  set token(v) { v ? localStorage.setItem("recognition.gh_token", v) : localStorage.removeItem("recognition.gh_token"); },
  get on() { return !!this.token; },
  get authToken() { return this.token || DEMO_KEY; },
  get canDispatch() { return !!this.authToken; },
  get pollMs() { return this.authToken ? 5000 : 12000; },

  async api(path, opts = {}) {
    const headers = {
      Accept: "application/vnd.github+json",
      "X-GitHub-Api-Version": "2022-11-28",
      ...(opts.headers || {}),
    };
    if (this.authToken) headers.Authorization = `Bearer ${this.authToken}`;
    const r = await fetch(`https://api.github.com${path}`, { ...opts, headers });
    if (r.status === 404) return null;
    if (!r.ok) throw new Error(`GitHub ${r.status}: ${(await r.text()).slice(0, 140)}`);
    return r.status === 204 ? true : r.json();
  },

  /* One trigger path for every credential: workflow_dispatch needs only the
     Actions:write scope, which is exactly all the demo key has. */
  async workflowDispatch(file, inputs) {
    const r = await fetch(`https://api.github.com/repos/${this.repo}/actions/workflows/${file}/dispatches`, {
      method: "POST",
      headers: {
        Accept: "application/vnd.github+json",
        Authorization: `Bearer ${this.authToken}`,
        "X-GitHub-Api-Version": "2022-11-28",
      },
      body: JSON.stringify({ ref: "main", inputs }),
    });
    if (!r.ok) throw new Error(`GitHub ${r.status}: ${(await r.text()).slice(0, 140)}`);
    return true;
  },

  /* Relay reads. The CDN mirror needs no credential but can lag ~a minute;
     the API serves fresh but unauthenticated calls are scarce (60/h). So:
     poll the cheap way while a run is in flight, and fetch fresh the moment
     it completes (relayFresh) — that is what makes results feel instant. */
  async raw(path, ref) {
    if (!this.token) {
      const r = await fetch(
        `https://raw.githubusercontent.com/${this.repo}/${ref}/${path}?t=${Date.now()}`,
        { cache: "no-store" },
      );
      return r.ok ? r.json().catch(() => null) : null;
    }
    const r = await fetch(
      `https://api.github.com/repos/${this.repo}/contents/${path}?ref=${ref}&t=${Date.now()}`,
      { headers: { Accept: "application/vnd.github.raw+json", Authorization: `Bearer ${this.token}` } },
    );
    return r.ok ? r.json() : null;
  },

  async relayFresh(path) {
    const headers = { Accept: "application/vnd.github.raw+json" };
    // a personal token may read contents; the demo key may not — plain
    // unauthenticated works for a public repo and is spent sparingly
    if (this.token) headers.Authorization = `Bearer ${this.token}`;
    try {
      const r = await fetch(
        `https://api.github.com/repos/${this.repo}/contents/${path}?ref=studio-interviews&t=${Date.now()}`,
        { headers },
      );
      if (r.ok) return await r.json();
    } catch { /* fall through to the mirror */ }
    return this.raw(path, "studio-interviews");
  },

  async findRun(workflow, sinceMs) {
    const d = await this.api(`/repos/${this.repo}/actions/runs?per_page=12`);
    return (d?.workflow_runs || []).find(
      (r) => r.path?.endsWith(`/${workflow}.yml`) && Date.parse(r.created_at) >= sinceMs - 20000,
    ) || null;
  },
};

