94	function b64(s) { return btoa(String.fromCharCode(...new TextEncoder().encode(s))); }
95	function triggerCommand(workflow, field, payload, extra = "") {
96	  return `gh workflow run ${workflow} --repo ${GH.repo} --ref main${extra} -f ${field}="$(echo ${b64(JSON.stringify(payload))} | base64 -d)"`;
97	}
