cat > web/glass.css <<'CSS'
/* Recognition — the drafting-light theme.
 *
 * Palette (as specified): 000814 · 001D3D · 003566 · FFC300 · FFD60A.
 * Deliberately NOT a dark theme: the page is a lit drafting table, the deep
 * navies carry type and depth, and the yellows are reserved for the one
 * action that matters. Rules that hold it together:
 *
 *   1. Yellow never carries text on light — FFC300 is a *fill* with near-black
 *      on top (≈13:1). Links and secondary actions use Yale blue instead.
 *   2. Every text surface is strong glass (≥.62 white) so body copy clears
 *      4.5:1 against the scene behind it.
 *   3. Verdict colour (pass/fail) is reserved for verdicts. The brand yellow
 *      is never used to mean "good".
 *   4. Floating elements are drawings — an isometric massing, a dimension
 *      line, a section hatch — placed on the thirds, never behind body text.
 */

:root {
  /* palette */
  --navy-900: #000814;
  --navy-800: #001d3d;
  --navy-600: #003566;
  --gold-500: #ffc300;
  --gold-400: #ffd60a;

  /* type */
  --ink: #001d3d;
  --ink-2: #2c4a70;
  --ink-3: #52709a;
  --on-accent: #000814;

  /* surfaces */
  --glass: rgba(255, 255, 255, 0.46);
  --glass-strong: rgba(255, 255, 255, 0.68);
  --glass-soft: rgba(255, 255, 255, 0.3);
  --glass-ink: rgba(0, 8, 20, 0.82);
  --glass-line: rgba(255, 255, 255, 0.7);
  --glass-line-soft: rgba(0, 53, 102, 0.14);
  --blur: blur(20px) saturate(1.4);

  /* verdicts — never decoration */
  --pass: #10693f;
  --fail: #bb2d20;
  --warn: #8a5a00;

  --shadow: 0 14px 44px rgba(0, 29, 61, 0.13), 0 2px 8px rgba(0, 29, 61, 0.07);
  --shadow-soft: 0 6px 22px rgba(0, 29, 61, 0.1);
  --shadow-lift: 0 20px 56px rgba(0, 29, 61, 0.18);
  --r: 20px;
  --r-sm: 13px;

  --font-display: "Bricolage Grotesque", "Helvetica Neue", sans-serif;
  --font-ui: "Sora", "Helvetica Neue", system-ui, sans-serif;
  --font-mono: "IBM Plex Mono", ui-monospace, Menlo, monospace;
}

* { box-sizing: border-box; }
html, body { margin: 0; height: 100%; }
body {
  font-family: var(--font-ui); font-size: 14.5px; line-height: 1.55; color: var(--ink);
  overflow: hidden; -webkit-font-smoothing: antialiased;
}
a { color: var(--navy-600); text-decoration: none; }
a:hover { text-decoration: underline; }
button { font: inherit; color: inherit; cursor: pointer; }
.mono, code, pre { font-family: var(--font-mono); }
.mini { font-size: 12px; color: var(--ink-3); }
.hide { display: none !important; }
:focus-visible { outline: 2px solid var(--navy-600); outline-offset: 2px; border-radius: 4px; }
@media (prefers-reduced-motion: reduce) { *, *::before, *::after { animation: none !important; transition: none !important; } }

/* ---- the scene: a lit drafting table ------------------------------------ */
.bg { position: fixed; inset: 0; z-index: -3;
  background: linear-gradient(152deg, #eef3fb 0%, #e9eff9 38%, #f7f1e2 82%, #fdf7e8 100%); }
.bg::before {
  content: ""; position: absolute; inset: -18%;
  background:
    radial-gradient(36% 44% at 18% 20%, rgba(0, 53, 102, 0.16), transparent 70%),
    radial-gradient(30% 36% at 82% 16%, rgba(255, 195, 0, 0.20), transparent 70%),
    radial-gradient(44% 52% at 76% 84%, rgba(0, 29, 61, 0.10), transparent 72%);
  filter: blur(46px);
}
/* the drafting grid, in ink rather than a tint of nothing */
.bg::after {
  content: ""; position: absolute; inset: 0; opacity: 0.55;
  background:
    repeating-linear-gradient(0deg, rgba(0, 53, 102, 0.055) 0 1px, transparent 1px 46px),
    repeating-linear-gradient(90deg, rgba(0, 53, 102, 0.055) 0 1px, transparent 1px 46px);
  mask-image: radial-gradient(88% 88% at 50% 38%, #000 28%, transparent 100%);
}

/* ---- floating drawings: architecture, not confetti ---------------------- */
.plate { position: fixed; z-index: -2; pointer-events: none; color: var(--navy-600); }
.plate svg { display: block; width: 100%; height: auto; overflow: visible; }
.plate--massing { top: 12vh; right: 4vw; width: min(360px, 26vw); opacity: 0.16;
  animation: drift 22s ease-in-out infinite; }
.plate--dim { bottom: 16vh; left: 5vw; width: min(300px, 24vw); opacity: 0.2; }
.plate--hatch { top: 46vh; left: -2vw; width: min(190px, 15vw); opacity: 0.13;
  animation: drift 28s ease-in-out infinite reverse; }
.plate--north { top: 16vh; left: 8vw; width: 74px; opacity: 0.15; }
@keyframes drift {
  0%, 100% { transform: translate3d(0, 0, 0); }
  50%      { transform: translate3d(0, -14px, 0); }
}
/* the drawings step back the moment real work is on the stage */
body.split .plate, body.working .plate { opacity: 0.07; }
@media (max-width: 1100px) { .plate--massing, .plate--hatch, .plate--north { display: none; } }
@media (max-width: 760px) { .plate { display: none; } }

/* ---- glass primitives --------------------------------------------------- */
.glass {
  background: var(--glass);
  -webkit-backdrop-filter: var(--blur); backdrop-filter: var(--blur);
  border: 1px solid var(--glass-line);
  box-shadow: var(--shadow), inset 0 1px 0 rgba(255, 255, 255, 0.8);
  border-radius: var(--r);
}
.pill, .glass-pill {
  display: inline-flex; align-items: center; gap: 7px;
  background: var(--glass-strong);
  -webkit-backdrop-filter: var(--blur); backdrop-filter: var(--blur);
  border: 1px solid var(--glass-line);
  box-shadow: var(--shadow-soft), inset 0 1px 0 rgba(255, 255, 255, 0.85);
  border-radius: 999px; padding: 9px 16px; font-size: 13.5px; font-weight: 500;
  color: var(--ink);
  transition: transform .18s ease-out, box-shadow .18s ease-out, background .18s;
}
.pill:hover, .glass-pill:hover { transform: translateY(-1px); background: rgba(255, 255, 255, 0.82); }
.pill:active, .glass-pill:active { transform: translateY(0); }
.pill:disabled { opacity: .5; cursor: default; transform: none; }
.pill.sm { padding: 5px 11px; font-size: 12px; }
.pill.primary {
  background: linear-gradient(140deg, var(--gold-400), var(--gold-500));
  color: var(--on-accent); border-color: rgba(0, 8, 20, .16); font-weight: 700;
  box-shadow: 0 6px 18px rgba(255, 195, 0, .34), inset 0 1px 0 rgba(255, 255, 255, .6);
}
.pill.primary:hover { background: linear-gradient(140deg, #ffdf3d, var(--gold-500)); }
.pill.primary[data-state="busy"] { opacity: .62; cursor: progress; }

/* ---- top bar ------------------------------------------------------------ */
.bar { position: fixed; top: 16px; left: 18px; right: 18px; z-index: 40;
  display: flex; align-items: center; gap: 10px; pointer-events: none; }
.bar > * { pointer-events: auto; }
.brand { font-weight: 700; letter-spacing: .01em; color: var(--ink); }
.brand:hover { text-decoration: none; }
.brand svg { width: 20px; height: 20px; }
.brand em { font-style: normal; font-weight: 400; color: var(--ink-2); font-size: 12.5px; margin-left: 2px; }
.bar .spacer { flex: 1; }
#connect[data-on="1"] { color: var(--pass); font-weight: 600; }

.connect-wrap { position: relative; }
.pop {
  position: absolute; right: 0; top: calc(100% + 10px); width: min(350px, calc(100vw - 32px));
  background: rgba(255, 255, 255, .88);
  -webkit-backdrop-filter: var(--blur); backdrop-filter: var(--blur);
  border: 1px solid var(--glass-line); border-radius: var(--r-sm);
  box-shadow: var(--shadow); padding: 15px 17px; z-index: 60;
}
.pop h3 { margin: 0 0 5px; font-size: 14px; font-family: var(--font-display); }
.pop .mini { margin: 0 0 10px; }
.pop input {
  width: 100%; font-family: var(--font-mono); font-size: 12.5px; padding: 9px 11px;
  border: 1px solid var(--glass-line-soft); border-radius: 9px; background: #fff; color: var(--ink);
}
.pop input:focus { border-color: var(--navy-600); outline: none; }
.pop-row { display: flex; align-items: center; gap: 8px; margin-top: 10px; }

/* ---- stage -------------------------------------------------------------- */
.stage { position: fixed; inset: 0; padding: 84px 20px 210px; overflow-y: auto;
  display: flex; flex-direction: column; align-items: center; }
.st { width: 100%; max-width: 1120px; margin: 0 auto; animation: rise .32s ease-out; }
@keyframes rise { from { opacity: 0; transform: translateY(10px); } to { opacity: 1; transform: none; } }

#st-hero { text-align: center; padding-top: 7vh; }
.display {
  font-family: var(--font-display); font-weight: 700; font-size: clamp(40px, 6.6vw, 78px);
  line-height: 1.01; letter-spacing: -.025em; margin: 0 0 18px; color: var(--ink);
}
/* the accent word is underlined in gold rather than set in it — yellow type
   on a light ground is unreadable, a gold rule under navy is not */
.display b { position: relative; color: var(--navy-800); font-weight: 700; white-space: nowrap; }
.display b::after {
  content: ""; position: absolute; left: -2px; right: -2px; bottom: .1em; height: .28em;
  background: linear-gradient(90deg, var(--gold-500), var(--gold-400));
  border-radius: 3px; z-index: -1; opacity: .95;
}
#st-hero .sub { max-width: 56ch; margin: 0 auto; color: var(--ink-2); font-size: 16px; }
#st-hero .sub b { font-weight: 600; color: var(--ink); }

/* drafting */
#st-drafting { display: flex; justify-content: center; padding-top: 6vh; }
.drafting { max-width: 560px; width: 100%; padding: 26px 28px; }
.drafting h2 { font-family: var(--font-display); font-size: 24px; margin: 0 0 4px; }
.blueprint-anim { height: 5px; border-radius: 3px; margin-bottom: 18px; overflow: hidden;
  background: rgba(0, 53, 102, .14); position: relative; }
.blueprint-anim::after {
  content: ""; position: absolute; inset: 0; width: 40%;
  background: linear-gradient(90deg, transparent, var(--gold-500), transparent);
  animation: sweep 1.6s ease-in-out infinite;
}
@keyframes sweep { 0% { transform: translateX(-100%); } 100% { transform: translateX(350%); } }
@media (prefers-reduced-motion: reduce) { .blueprint-anim::after { animation: none; width: 100%; opacity: .5; } }
.draft-steps { list-style: none; margin: 14px 0 0; padding: 0; display: flex; flex-direction: column; gap: 7px; }
.dstep { display: flex; align-items: center; gap: 10px; font-size: 13px; color: var(--ink-2); }
.dstep .dot { width: 8px; height: 8px; border-radius: 50%; background: rgba(0, 29, 61, .2); flex: none; }
.dstep.run .dot { background: var(--gold-500); animation: pulse 1.1s ease-in-out infinite; }
.dstep.done .dot { background: var(--pass); }
.dstep.fail .dot { background: var(--fail); }
.dstep.pend { opacity: .55; }
.dstep .lb { flex: 1; }
.dstep .rt { font-family: var(--font-mono); font-size: 11px; color: var(--ink-3); }
@keyframes pulse { 0%, 100% { opacity: 1; } 50% { opacity: .35; } }

/* ---- options ------------------------------------------------------------ */
.stage-h { font-family: var(--font-display); font-size: clamp(22px, 3vw, 30px); margin: 0 0 18px; text-align: center; }
.options { display: grid; grid-template-columns: repeat(auto-fit, minmax(300px, 1fr)); gap: 18px; }
.opt { overflow: hidden; display: flex; flex-direction: column; cursor: zoom-in;
  animation: rise .32s ease-out backwards; animation-delay: calc(var(--i, 0) * 60ms);
  transition: transform .2s ease-out, box-shadow .2s ease-out; }
.opt:hover { transform: translateY(-3px); box-shadow: var(--shadow-lift), inset 0 1px 0 rgba(255,255,255,.8); }
.opt-sheet { position: relative; background: rgba(255, 255, 255, .92); padding: 10px;
  min-height: 200px; display: flex; align-items: center; justify-content: center; }
.opt-sheet svg { max-width: 100%; height: auto; max-height: 230px; }
.sheet-count { position: absolute; right: 10px; bottom: 8px; font-size: 10.5px; color: var(--ink-3);
  background: rgba(255,255,255,.85); border-radius: 999px; padding: 2px 8px; }
.opt-sheet.dead { flex-direction: column; gap: 8px; background: rgba(255,255,255,.6); color: var(--ink-3); }
.dead-mark { font-family: var(--font-mono); font-size: 30px; color: rgba(0,29,61,.22); }
.opt-dead { cursor: default; }
.opt-meta { padding: 14px 16px 16px; display: flex; flex-direction: column; gap: 8px; cursor: default; }
.opt-head { display: flex; align-items: center; justify-content: space-between; gap: 10px; }
.opt-name { font-family: var(--font-display); font-size: 17px; margin: 0; }
.opt-desc { margin: 0; font-size: 12.5px; color: var(--ink-2); min-height: 2.6em; }
.opt-facts { display: flex; gap: 14px; font-size: 11.5px; color: var(--ink-2); }
.opt .pill.primary { align-self: flex-start; margin-top: 2px; }

.code-pill { display: inline-flex; align-items: center; border: 0; border-radius: 999px;
  font-family: var(--font-mono); font-size: 10.5px; font-weight: 600; letter-spacing: .02em;
  padding: 5px 10px; white-space: nowrap; }
.code-pill.ok { background: rgba(16, 105, 63, .13); color: var(--pass); }
.code-pill.bad { background: rgba(187, 45, 32, .13); color: var(--fail); }
.code-pill:hover { filter: brightness(.94); }

/* ---- takes strip + detail ----------------------------------------------- */
.takes { display: flex; flex-wrap: wrap; gap: 8px; margin: 0 0 14px; }
.take { display: inline-flex; align-items: baseline; gap: 8px;
  background: var(--glass-strong); -webkit-backdrop-filter: var(--blur); backdrop-filter: var(--blur);
  border: 1px solid var(--glass-line); border-radius: 999px; padding: 8px 15px;
  font-size: 13px; font-weight: 500; color: var(--ink); transition: transform .16s, background .16s; }
.take:hover { transform: translateY(-1px); background: rgba(255, 255, 255, .85); }
.take.on { border-color: var(--gold-500); box-shadow: 0 0 0 2px var(--gold-500), var(--shadow-soft); font-weight: 600; }
.take .tdot { font-family: var(--font-mono); font-size: 11px; font-weight: 700; }
.take .tdot.ok { color: var(--pass); }
.take .tdot.bad { color: var(--fail); }
.take .tm { font-size: 11px; color: var(--ink-3); }
.take.all { color: var(--navy-600); border-style: dashed; }

.viewer { position: relative; height: min(56vh, 600px); overflow: hidden; background: var(--glass-soft); }
#v3-host { position: absolute; inset: 0; cursor: grab; }
#v3-host:active { cursor: grabbing; }
.v3-canvas { display: block; width: 100% !important; height: 100% !important; }
.v3-wait { position: absolute; inset: 0; display: flex; align-items: center; justify-content: center;
  font-family: var(--font-mono); font-size: 12.5px; color: var(--ink-3); pointer-events: none; }
.hoverchip { position: absolute; pointer-events: none; z-index: 3; transform: translate(-50%, -140%);
  background: var(--glass-ink); color: #fff; -webkit-backdrop-filter: blur(8px); backdrop-filter: blur(8px);
  font-family: var(--font-mono); font-size: 11.5px; padding: 6px 10px; border-radius: 9px; white-space: nowrap; }
.viewer-foot { position: absolute; left: 14px; bottom: 12px; right: 14px;
  display: flex; align-items: baseline; gap: 12px; flex-wrap: wrap;
  background: rgba(255, 255, 255, .8); -webkit-backdrop-filter: var(--blur); backdrop-filter: var(--blur);
  border: 1px solid var(--glass-line); border-radius: var(--r-sm); padding: 9px 14px; }
#detail-name { font-family: var(--font-display); font-weight: 600; font-size: 15px; }
#detail-metrics { font-size: 11.5px; color: var(--ink-2); }

.sheet-panel { margin-top: 16px; overflow: hidden; }
.sheet-panel-head { display: flex; align-items: center; gap: 12px; padding: 12px 16px 10px; flex-wrap: wrap; }
.sheet-panel-head strong { font-family: var(--font-display); font-size: 14.5px; }
.sheet-tabs { display: inline-flex; gap: 6px; }
.sheet-tab { border: 1px solid var(--glass-line-soft); background: rgba(255,255,255,.7);
  border-radius: 999px; padding: 4px 12px; font-size: 12px; color: var(--ink-2); }
.sheet-tab.on { background: var(--navy-800); border-color: var(--navy-800); color: #fff; font-weight: 600; }
#sheet-inline { display: block; width: 100%; border: 0; padding: 12px 16px 16px;
  background: rgba(255, 255, 255, .93); cursor: zoom-in; text-align: center; }
#sheet-inline:hover { background: #fff; }
#sheet-inline svg { max-width: 100%; height: auto; max-height: 46vh; }
.cmd-fold summary { font-size: 12px; color: var(--ink-2); cursor: pointer; padding: 4px 0; }

/* ---- drawers ------------------------------------------------------------ */
.drawer { position: fixed; top: 16px; right: 16px; bottom: 16px; width: min(400px, calc(100vw - 32px));
  z-index: 50; padding: 20px 22px; overflow-y: auto;
  background: rgba(255, 255, 255, .88); animation: slide .26s ease-out; }
@keyframes slide { from { opacity: 0; transform: translateX(24px); } to { opacity: 1; transform: none; } }
