.dot-pill { font-family: var(--font-mono); font-size: 11px; font-weight: 700; }
.dot-pill.ok { color: var(--pass); }
.dot-pill.bad { color: var(--fail); }

/* ---- sheet lightbox ----------------------------------------------------- */
