  document.querySelector('#portfolio-drawer .drawer-x')?.click();
  return { deadInfo, portfolioSections: heads, portfolioItems: items };
})()

(async () => {
  // take a real key from the live index so the "Yours" split is proven
  const S = window.__studio;
  const idx = await S.loadIndex();
  const keys = idx.projects.map(p => p.key);
  localStorage.setItem('recognition.mine', JSON.stringify([keys[0]]));
  document.getElementById('portfolio-pill').click();
  await new Promise(r => setTimeout(r, 700));
  const heads = [...document.querySelectorAll('#portfolio-list .drawer-h')].map(h => h.textContent);
  const notes = [...document.querySelectorAll('#portfolio-list > .mini')].map(n => n.textContent);
  document.querySelector('#portfolio-drawer .drawer-x')?.click();
  localStorage.removeItem('recognition.mine');
  return { keys, heads, notes };
})()

(async () => {
  const idx = await fetch('data/index.json').then(r => r.ok ? r.json() : { projects: [] }).catch(() => ({ projects: [] }));
  const keys = (idx.projects || []).map(p => p.key);
  if (keys.length) localStorage.setItem('recognition.mine', JSON.stringify([keys[0]]));
  document.getElementById('portfolio-pill').click();
  await new Promise(r => setTimeout(r, 700));
  const heads = [...document.querySelectorAll('#portfolio-list .drawer-h')].map(h => h.textContent);
  document.querySelector('#portfolio-drawer .drawer-x')?.click();
  localStorage.removeItem('recognition.mine');
  return { keyCount: keys.length, firstKey: keys[0], heads };
})()

(async () => {
  const S = window.__studio;
  const bundle = await fetch('test-bundle.json').then(r => r.json());
  S.Draft.bundle = bundle; S.renderOptions(bundle); S.stage('options');
  return "options staged";
})()

(async () => {
  const S = window.__studio;
  const bundle = window.__b || (window.__b = await fetch('test-bundle.json').then(r => r.json()));
  S.selectCandidate(bundle.candidates[0]);
  await new Promise(r => setTimeout(r, 2400));
  return "detail staged, mesh " + (document.getElementById('v3-wait').classList.contains('hide') ? "loaded" : "pending");
})()

(() => {
  const dock = document.getElementById('dock').getBoundingClientRect();
  const viewer = document.querySelector('.viewer').getBoundingClientRect();
  const sheet = document.querySelector('.sheet-panel').getBoundingClientRect();
  const tabs = [...document.querySelectorAll('.sheet-tab')].map(t => t.textContent);
  const cs = getComputedStyle(document.body);
  return {
    split: document.body.classList.contains('split'),
    dockRightSidebar: dock.left > 1000 && dock.width < 400,
    viewerLeftOfDock: viewer.right < dock.left,
    sheetBelowViewer: sheet.top >= viewer.bottom - 2,
    storeyTabs: tabs,
    bodyColor: cs.color, // navy ink, not white — proves light theme
    canvas: !!document.querySelector('.viewer canvas'),
    metrics: document.getElementById('detail-metrics').textContent,
  };
})()

